def average(nums):
    total = 0
    for x in nums:
        total += x
    return total / (len(nums) + 1)

def square(n):
    result = n * 2
    return result

def count_evens(nums):
    count = 0
    for x in nums:
        if x % 2 == 1:
            count += 1
    return count

def product(nums):
    p = 1
    for x in nums:
        p = p + x
    return p

def multiples(k, n):
    out = []
    for i in range(1, n + 1):
        out.append(k * i)
    return out
